Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CX.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x7 x8 x9 x13 x21 x22 x25 x28 x29 : word) (x6 x15 x23 : word).
  Variables (m : fmem) (DT SY b e nb tl : Z) (sorted : list (option Z)) (js jt : list byte) (ncells : nat).
  Variable POST : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis HDT : 0 < DT /\ DT + 4 + 4 * Z.of_nat ncells <= 2^47.
  Hypothesis DJ : DT + 4 + 4 * Z.of_nat ncells <= SY \/ SY + 256 <= DT + 4.
  Hypothesis HSY : 0 < SY /\ SY + 256 <= 2^47.
  Hypothesis HNB : 1 <= nb <= 12.
  Hypothesis HTL : tl - nb = 3.
  Hypothesis HBE : 0 <= b <= e /\ e <= 256.
  Notation INV m1 dt := (x2f_inv m m1 DT SY js jt sorted ncells dt).
  Notation D := (nb * 65536 + 16777216).

  Lemma c1d_inner : forall f s dt u m1 r (x5 x16 x17 : word),
    fill_for_weight f dt u s e nb tl 0 1 sorted = Ok r ->
    Z.of_nat f = e - s + 1 -> b <= s < e -> 0 <= u -> INV m1 dt ->
    (forall m2 dt' (y5 y10 y12 y14 y16 y17 : word),
       r = (dt', u + 8 * (e - s)) -> INV m2 dt' ->
       evt psegs POST (MS (mkR x1 sp gp tp y5 x6 x7 x8 x9 y10 (Z_to_bv 64 D) y12 x13 y14 x15 y16 y17 (Z_to_bv 64 2)
                               (Z_to_bv 64 4) (Z_to_bv 64 8) x21 x22 x23 (Z_to_bv 64 SY) x25 (Z_to_bv 64 e) (Z_to_bv 64 b)
                               x28 x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
                          F (Z_to_bv 64 0x13d00) fc None m2 (seg_rom psegs))) ->
    evt psegs POST (MS (mkR x1 sp gp tp x5 x6 x7 x8 x9 (Z_to_bv 64 (SY + s)) (Z_to_bv 64 D) (Z_to_bv 64 (DT + 4 + 4 * u)) x13
                            (Z_to_bv 64 (e - s)) x15 x16 x17 (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 8) x21 x22 x23
                            (Z_to_bv 64 SY) x25 (Z_to_bv 64 e) (Z_to_bv 64 b) x28 x29 (Z_to_bv 64 1) (Z_to_bv 64 3))
